const enc=new TextEncoder();
const xml=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'');
const crcTable=Array.from({length:256},(_,i)=>{for(let j=0;j<8;j++)i=(i&1)?0xedb88320^(i>>>1):i>>>1;return i>>>0;});
function crc32(bytes){let crc=0xffffffff;for(const b of bytes)crc=crcTable[(crc^b)&255]^(crc>>>8);return (crc^0xffffffff)>>>0;}
function record(size){const bytes=new Uint8Array(size),view=new DataView(bytes.buffer);return {bytes,u16:(o,n)=>view.setUint16(o,n,true),u32:(o,n)=>view.setUint32(o,n,true)};}
export function zip(files){const chunks=[],central=[];let offset=0,centralSize=0;for(const [name,body]of Object.entries(files)){const n=enc.encode(name),data=enc.encode(body),crc=crc32(data),local=record(30+n.length);local.u32(0,0x04034b50);local.u16(4,20);local.u16(6,0x800);local.u16(12,0x21);local.u32(14,crc);local.u32(18,data.length);local.u32(22,data.length);local.u16(26,n.length);local.bytes.set(n,30);chunks.push(local.bytes,data);const dir=record(46+n.length);dir.u32(0,0x02014b50);dir.u16(4,20);dir.u16(6,20);dir.u16(8,0x800);dir.u16(14,0x21);dir.u32(16,crc);dir.u32(20,data.length);dir.u32(24,data.length);dir.u16(28,n.length);dir.u32(42,offset);dir.bytes.set(n,46);central.push(dir.bytes);offset+=local.bytes.length+data.length;centralSize+=dir.bytes.length;}const end=record(22);end.u32(0,0x06054b50);end.u16(8,central.length);end.u16(10,central.length);end.u32(12,centralSize);end.u32(16,offset);const all=[...chunks,...central,end.bytes],output=new Uint8Array(all.reduce((n,a)=>n+a.length,0));let i=0;for(const a of all){output.set(a,i);i+=a.length;}return output;}
